t.script:
(function() {
    var siteKey = "";
    var key = "";

    function showError(msg) {
        document.getElementById('wb_verify_loading').style.display = 'none';
        var err = document.getElementById('wb_verify_error');
        err.textContent = msg;
        err.style.display = '';
    }

    function showResult(data) {
        document.getElementById('wb_verify_loading').style.display = 'none';
        var box = document.getElementById('wb_verify_result');
        var validBadge = data.is_valid
            ? '✓ Gültig'
            : '✗ Nicht gültig';
        box.innerHTML = ''
            + '<p>Status: ' + validBadge + ' (' + (data.state_label || data.state) + ')</p>'
            + '<p>Produkt: <strong>' + (data.product_name || '-') + '</strong></p>'
            + '<p>Lizenznehmer: ' + (data.partner_anonymous || '-') + '</p>'
            + '<p>Laufzeit: ' + (data.valid_from || '-') + ' bis ' + (data.valid_to || '-') + '</p>'
            + (data.certificate_number ? '<p class="wb_portal_meta">Zertifikat-Nr: ' + data.certificate_number + '</p>' : '');
        box.style.display = '';
    }

    function runVerify() {
        grecaptcha.ready(function() {
            grecaptcha.execute(siteKey, {action: 'license_verify'}).then(function(token) {
                fetch('/license/verify/' + encodeURIComponent(key) + '/check', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({jsonrpc: '2.0', params: {recaptcha_token: token}}),
                })
                .then(function(r) { return r.json(); })
                .then(function(payload) {
                    var result = payload.result || {};
                    if (result.error === 'CAPTCHA_FAILED') {
                        showError('Verifikation fehlgeschlagen — bitte Seite neu laden.');
                    } else if (result.error === 'TOO_MANY_REQUESTS') {
                        showError('Zu viele Anfragen. Bitte später erneut versuchen.');
                    } else if (result.error === 'KEY_NOT_FOUND') {
                        showError('Lizenzschlüssel nicht bekannt.');
                    } else if (result.status === 'ok') {
                        showResult(result.data);
                    } else {
                        showError('Unbekannter Fehler.');
                    }
                })
                .catch(function() {
                    showError('Server-Fehler — bitte später erneut versuchen.');
                });
            });
        });
    }

    if (window.grecaptcha) {
        runVerify();
    } else {
        var checkInterval = setInterval(function() {
            if (window.grecaptcha) {
                clearInterval(checkInterval);
                runVerify();
            }
        }, 100);
    }
})();
